import { publicCatalogueRead, blockNativeCatalogueWrite } from "$publicApi/site-client";
import { PUBLIC_API_URL } from "$env/static/public";
import { HTTP } from "$lib";

export const Manga = (id: string) => {
	if (Boolean(true)) return publicCatalogueRead<unknown>("analytics.manga", { id });
	const http = new HTTP(`${PUBLIC_API_URL}/analytics/manga/${id}/views`);
	return http.POST();
};

export const Chapter = (id: string) => {
	if (Boolean(true)) return publicCatalogueRead<unknown>("analytics.chapter", { id });
	const http = new HTTP(`${PUBLIC_API_URL}/analytics/chapter/${id}/views`);
	return http.POST();
};
